 ## Unreleased

+- Fix `daysLeft` and `isExpired` to use UTC calendar days and keep items valid through their expiry date.
 - Faster tag lookup.

 ## 1.4.2 - 2026-09-30
diff --git a/src/expiry.js b/src/expiry.js
index 0a7b267..6673c03 100644
--- a/src/expiry.js
+++ b/src/expiry.js
@@ -4,7 +4,10 @@ const DAY = 86400000;

 /** Whole days until the item expires (negative once expired). */
 export function daysLeft(item, now = Date.now()) {
-  return Math.floor((Date.parse(item.expires) - now) / DAY);
+  return (
+    Math.floor(new Date(item.expires).getTime() / DAY) -
+    Math.floor(new Date(now).getTime() / DAY)
+  );
 }

 /** True once the item has expired; logs a warning. */
@@ -14,5 +17,5 @@ export function isExpired(item, now = Date.now()) {
     log.warn("item expired", { id: item.id, days: left });
     return true;
   }
-  return left === 0;
+  return false;
 }
